with src as (select *, datediff(current_date(), last_restock) as days_since_last_restock from inventory where month(last_restock) in (4, 9, 10) and quantity between 208 and 238 and quantity > 193), summary as (select case when days_since_last_restock >= 60 then 'high' when days_since_last_restock >= 30 then 'mid' else 'low' end as days_since_last_restock_bucket, case when quantity >= 262 then 'high' when quantity >= 113 then 'mid' else 'low' end as quantity_bucket, min(last_restock) as first_last_restock from src group by case when days_since_last_restock >= 60 then 'high' when days_since_last_restock >= 30 then 'mid' else 'low' end, case when quantity >= 262 then 'high' when quantity >= 113 then 'mid' else 'low' end) select * from summary order by first_last_restock, days_since_last_restock_bucket desc
